-- Generated by build/rescue_descriptions.py -- do not edit.
-- gene.description rescued from the e114 cores into the e116 cores.
-- Matched on species.production_name AND gene.stable_id, both rows is_current=1.
-- Only rows whose e116 description IS NULL or '' are touched; nothing is overwritten.
-- These tables are MyISAM: no transactions, no rollback. Run 02 before 03, or
-- 99_rescue_revert.sql cannot restore exactly.

-- The copy is a cross-database join: the text never leaves the server.

SELECT IF((SELECT COUNT(*) FROM information_schema.TABLES
            WHERE TABLE_SCHEMA='actinidia_chinensis_core_70_116_1' AND TABLE_NAME='rescue_desc_bak')=1,
          'ok: backup present for actinidia_chinensis',
          'ABORT: run 02_rescue_backup.sql first') AS load_guard;
UPDATE `actinidia_chinensis_core_70_116_1`.gene n
  JOIN `actinidia_chinensis_core_69_114_1`.gene o ON o.stable_id = n.stable_id
   SET n.description = o.description
 WHERE n.is_current = 1 AND o.is_current = 1
   AND (n.description IS NULL OR n.description = '')
   AND o.description IS NOT NULL AND o.description <> '';
SELECT 'actinidia_chinensis' AS production_name, ROW_COUNT() AS updated, 32966 AS expected;

